local function C_3()
local script = LMG2L["LocalScript_3"];
local TweenService = game:GetService("TweenService");
local gui = script.Parent;

local DURACION = 2.5;  
local ESTILO = Enum.EasingStyle.Sine;  
local DIRECCION = Enum.EasingDirection.InOut;  

local esquina1 = UDim2.new(0.1, 0, 0.1, 0);  
local esquina2 = UDim2.new(0.85, 0, 0.85, 0);  

gui.Position = esquina1;  
gui.Rotation = 0;  
gui.AnchorPoint = Vector2.new(0.5, 0.5);  

local tweenInfo = TweenInfo.new(  
	DURACION,  
	ESTILO,  
	DIRECCION,  
	-1,   -- repetir infinitamente  
	true, -- reverse  
	0  
);  

local goal = {  
	Position = esquina2,  
	Rotation = 40  
};  

local tween = TweenService:Create(gui, tweenInfo, goal);  
tween:Play();

end

task.spawn(C_3);

print("✅ GUI + Música + Animación cargada correctamente");

